from taf.gnb.oam.ne3s.ws.filter import MessageStream, MessageRule
from abc import ABC, abstractproperty


class FunctionalComponent(ABC):
    @abstractproperty
    def STREAMS(self):
        raise NotImplementedError()

    @abstractproperty
    def _connection(self):
        raise NotImplementedError()

    @abstractproperty
    def SUPPORTED_NOTIFICATIONS(self):
        raise NotImplementedError()

    def add_new_msg_stream(self, stream_name, msg_list, size=1000, overwrite=False):
        if not isinstance(msg_list, tuple):
            msg_list = tuple(msg_list)
        new_stream = MessageStream(name=stream_name, rule=MessageRule(condition=msg_list), size=size)
        self._connection.notifications.add_streams(streams=(new_stream,), overwrite=overwrite)
        if overwrite is True:
            self._remove_duplicated_streams(stream_name)
        self.STREAMS.append(new_stream)

        return new_stream

    def remove_msg_stream(self, stream_name):
        for stream_index, stream in enumerate(self.STREAMS):
            if stream.name == stream_name:
                removed_stream = self.STREAMS.pop(stream_index)
                self._connection.notifications.remove_streams(streams=(removed_stream,))
                break
        else:
            err_msg = "Stream name: {} you want to remove does not exist in component streams {}"
            raise ValueError(err_msg.format(stream_name, self.STREAMS))

    def _remove_duplicated_streams(self, stream_name):
        for stream in self.STREAMS:
            if stream.name == stream_name:
                self.STREAMS.remove(stream)
